import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const read=async name=>JSON.parse((await fs.readFile(path.join(root,name),'utf8')).replace(/^\uFEFF/,''));
const content=await read('content.json'),state=await read('campaign-state.json');
if(!content.rules['机密'].maps.includes('核电站')||!content.rules['机密'].cards.some(c=>c.map==='核电站'))throw Error('Expected nuclear plant map and card rule in the prior revision.');
const backup=path.join(root,'review/before-secret-maps-r3');
await fs.mkdir(backup,{recursive:true});
for(const name of ['content.json','campaign-state.json','layout.json','layout-adapter.mjs','output/manifest.json','review/visual-qa.md','source/pack.ps1'])await fs.copyFile(path.join(root,name),path.join(backup,path.basename(name)));
const rule=content.rules['机密'];
rule.maps=rule.maps.filter(map=>map!=='核电站');
rule.cards=rule.cards.filter(card=>card.map!=='核电站');
const pageIds=['desktop-secret','mobile-secret'],revision='excess-secret-maps-r3-20261009';
content.deliveryPageIds=pageIds;
content.provenance.mechanismAndRules+=' 2026-10-09用户明确确认：删除机密版核电站及对应房卡说明，适用端游、手游。';
content.provenance.mapRevision={date:'2026-10-09',pageIds,confirmedByUser:'删除核电站及对应房卡说明',removedMap:'核电站',removedCardRule:'核电站含金红卡',remainingMaps:rule.maps};
content.provenance.sourceFiles=[...new Set([...content.provenance.sourceFiles,'source-references/mobile-secret-before-maps-r3-20261009.png','source-references/desktop-secret-before-maps-r3-20261009.png'])];
state.revisionHistory=[...(state.revisionHistory??[]),{revision:state.revision,package:state.package,basis:state.contentVerificationBasis}];
state.deliveryScope={pageIds,platforms:['desktop','mobile'],basis:'用户点名超额累计单机密版并提供端游、手游两张图，明确确认删除核电站及对应房卡说明，共2页。'};
state.contentVerificationBasis='用户2026-10-09明确回复“删除核电站及对应房卡说明”，端手游机密版均删除地图列表及房卡条目中的核电站。两端价目继续沿用已核对源数据，手游188/388/588/788r对应188/488/888/1288w。其余已确认机制、条件和补偿继续沿用。';
state.contentVerified=true;
state.plannedDeliverables=['端游·机密五档价目（删除核电站）','手游·机密四档价目（删除核电站）'];
state.revision=revision;
state.stage='rules-update';
state.package='campaign-'+revision+'.zip';
state.nextStep='导出端手游机密版，检查地图与房卡条目及相邻区域后打包。';
state.vectorDelivery={status:'in-progress',review:'review/index.html',overview:'review/maps-r3-overview.png',visualQA:'review/visual-qa.md',formats:['PNG','editable text SVG','outlined SVG'],pageIds,tierCount:9,reviewFiles:['review/visual-qa.md','review/maps-r3-audit.json','review/maps-r3-overview.png',...pageIds.flatMap(id=>['review/phone-390/'+id+'.png','review/maps-r3-details/'+id+'-maps.png'])]};
state.approvals.secretMapRemoval={status:'approved',date:'2026-10-09',basis:'用户明确选择：删除核电站及对应房卡说明',pageIds};
for(const [name,value] of [['content.json',content],['campaign-state.json',state]])await fs.writeFile(path.join(root,name),JSON.stringify(value,null,2)+'\n');
console.log(JSON.stringify({pageIds,remainingMaps:rule.maps,remainingCards:rule.cards}));
